<?php $this->layout('default'); use Moves\Services\CmsQuery as Q; use Moves\Services\SystemLog; use Moves\Support\CmsView as V;
$filters = ['q' => V::queryString('q'), 'level' => V::queryString('level'), 'status' => V::queryString('status')]; $result = SystemLog::listing($filters, V::queryPage()); $levels = ['error' => ['Erro', 'bad'], 'warning' => ['Atenção', 'warn'], 'notice' => ['Aviso', 'info']]; $n = static fn (string $s): string => (string) Q::value($s); ?>
<?php $this->start('actions'); ?><span class="cms-pill"><?= (int) $result['total'] ?> registro(s)</span><?php $this->stop(); ?>
<?= V::kpis([['pages', 'Total', $n('SELECT COUNT(*) FROM cms_system_logs'), 'ocorrências agrupadas'], ['clock', 'Em aberto', $n("SELECT COUNT(*) FROM cms_system_logs WHERE status='open'"), 'aguardando análise'], ['alert', 'Críticos', $n("SELECT COUNT(*) FROM cms_system_logs WHERE status='open' AND level='error'"), 'erros em aberto'], ['clock', 'Últimas 24h', $n('SELECT COUNT(*) FROM cms_system_logs WHERE last_seen_at >= NOW() - INTERVAL 1 DAY'), 'atividade recente']]) ?>
<section class="cms-list"><?= V::listHead('Incidentes encontrados', 'Sem dados de clientes nem segredos', V::searchForm('Mensagem ou arquivo', ['level' => [$filters['level'], ['' => 'Todos os níveis', 'error' => 'Erro', 'warning' => 'Atenção', 'notice' => 'Aviso'], 'Nível'], 'status' => [$filters['status'], ['' => 'Todas', 'open' => 'Aberto', 'resolved' => 'Resolvido'], 'Situação']])) ?>
<?php if ($result['rows'] === []): ?><?= V::empty('Nenhum incidente registrado.') ?><?php else: ?><form method="post" action="/acao/system-log-resolve"><?= V::csrf() ?><div class="cms-log"><?php foreach ($result['rows'] as $l): [$label, $tone] = $levels[$l['level']]; ?><details><summary><input type="checkbox" name="ids[]" value="<?= (int) $l['id'] ?>" aria-label="Selecionar ocorrência"><span class="cms-level cms-level-<?= $tone ?>"><?= V::e($label) ?></span><span class="cms-log-main"><strong><?= V::e(mb_strimwidth($l['message'], 0, 110, '…')) ?></strong><small><code><?= V::e($l['source']) ?></code> · <?= (int) $l['occurrences'] ?>x · <?= V::date($l['last_seen_at']) ?></small></span><?= V::badge($l['status'] === 'open' ? 'overdue' : 'active', $l['status'] === 'open' ? 'Aberto' : 'Resolvido') ?></summary><pre><?= V::e($l['message']) ?>

Caminho: <?= V::e($l['path']) ?>
Primeira vez: <?= V::date($l['first_seen_at']) ?></pre></details><?php endforeach; ?></div><div class="cms-bulkbar"><button class="cms-btn">Marcar selecionados como resolvidos</button></div></form><?= V::pager($result) ?><?php endif; ?></section>
